using UnityEngine;
using UnityEditor;
using System;
using System.IO;
using System.Linq;
using System.Text;
using ConRoi.Investigation.V36.R103;
using Object = UnityEngine.Object;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult r)
        {
            var s = Object.FindFirstObjectByType<InvestigationSession>();
            if (!EditorApplication.isPlaying)
                throw new Exception("Play required");
            s.SaveDirectoryOverride = Path.GetFullPath("Test/KetQua/investigation_r103/presentation-ui-profile");
            var w = EditorWindow.GetWindow(Type.GetType("UnityEditor.GameView,UnityEditor"));
            w.minSize = w.maxSize = new Vector2(1024, 597.2f);
            w.position = new Rect(0, 0, 1024, 597.2f);
            w.Focus();
            Action<float, float> click = (x, y) =>
            {
                var p = new Vector2(x * Screen.width / 1200 / 1.25f, y * Screen.height / 800 / 1.25f + 55f);
                w.SendEvent(new Event{type = EventType.MouseDown, button = 0, mousePosition = p});
                w.SendEvent(new Event{type = EventType.MouseUp, button = 0, mousePosition = p});
            };
            var ids = new[]{"release", "help", "hold", "hook", "wedge", "after"};
            int phase = -2, shot = 0;
            double start = EditorApplication.timeSinceStartup;
            float last = -1;
            var log = new StringBuilder("Silent video. Synthetic GameView mouse controls select playback/replay/pause/seek and all six cases. API opens clip/reconstruction pages only; no prescribed trial results. Not controller traversal evidence.\n");
            s.Acquire("clip");
            s.OpenPage("clip");
            s.UpdateClip();
            EditorApplication.CallbackFunction tick = null;
            tick = () =>
            {
                if (!EditorApplication.isPlaying)
                {
                    EditorApplication.update -= tick;
                    return;
                }

                float t = (float)(EditorApplication.timeSinceStartup - start);
                try
                {
                    if (phase == -2)
                    {
                        if (t < 1)
                            return;
                        click(950, 555);
                        phase = -1;
                        start = EditorApplication.timeSinceStartup;
                        last = -1;
                        return;
                    }

                    if (phase == -1)
                    {
                        foreach (float a in new[]{1f, 3.8f, 4.35f, 4.9f, 6f})
                            if (last < a && t >= a)
                                ScreenCapture.CaptureScreenshot("Test/BangChung/investigation_r103/clip-final-" + a.ToString("F2", System.Globalization.CultureInfo.InvariantCulture) + ".png");
                        if (t > 12.5f)
                        {
                            log.AppendLine("clip before=" + s.data.clipBeforeSeen + " event=" + s.data.clipEventSeen + " stopped=" + !s.ClipPlaying);
                            click(800, 555);
                            phase = -3;
                            start = EditorApplication.timeSinceStartup;
                            return;
                        }
                    }
                    else if (phase == -3)
                    {
                        if (t > .8 && shot == 0)
                        {
                            click(450, 555);
                            log.AppendLine("replay via button time=" + s.ClipTime + " playing=" + s.ClipPlaying);
                            shot++;
                        }

                        if (t > 1.4 && shot == 1)
                        {
                            click(450, 555);
                            shot++;
                        }

                        if (t > 2 && shot == 2)
                        {
                            click(950, 639);
                            shot++;
                        }

                        if (t > 2.5)
                        {
                            log.AppendLine("pause/seek time=" + s.ClipTime + " playing=" + s.ClipPlaying);
                            s.OpenPage("reconstruction");
                            phase = 0;
                            click(420, 170);
                            start = EditorApplication.timeSinceStartup;
                            last = -1;
                            return;
                        }
                    }
                    else
                    {
                        foreach (float a in new[]{1f, 3f, 5.5f, 8f})
                            if (last < a && t >= a)
                            {
                                ScreenCapture.CaptureScreenshot("Test/BangChung/investigation_r103/case-" + ids[phase] + "-" + a.ToString("F1", System.Globalization.CultureInfo.InvariantCulture) + ".png");
                                log.AppendLine(ids[phase] + " t=" + s.TrialTime + " angle=" + s.modelGate.state.angle + " latched=" + s.modelGate.state.latched + " rope=" + s.modelGate.state.rope + " hook=" + s.modelGate.state.hook + " body=" + s.modelGate.state.bodyForce + " wedge=" + s.modelGate.state.wedge);
                            }

                        if (t > 10.6f)
                        {
                            if (s.TrialId != ids[phase])
                                throw new Exception("UI wrong case " + ids[phase] + " actual=" + s.TrialId);
                            log.AppendLine("completed " + ids[phase] + " selected=" + s.TrialId + " " + s.TrialReport);
                            foreach (var h in s.GetComponentsInChildren<PresentationHands>())
                                log.AppendLine(h.name + " hand max target error=" + h.maxReachError);
                            phase++;
                            if (phase >= ids.Length)
                            {
                                s.Save();
                                File.WriteAllText("Test/KetQua/investigation_r103/presentation-ui.txt", log.ToString());
                                EditorApplication.update -= tick;
                                return;
                            }

                            click(420, 170 + phase * 41);
                            start = EditorApplication.timeSinceStartup;
                            last = -1;
                            return;
                        }
                    }

                    last = t;
                }
                catch (Exception e)
                {
                    EditorApplication.update -= tick;
                    File.WriteAllText("Test/KetQua/investigation_r103/presentation-ui.txt", log + "FAIL " + e);
                }
            };
            EditorApplication.update += tick;
            r.Log("Started 82s synthetic UI presentation review");
        }
    }
}

